html:
{%- macro line(label, value) -%}
{%- if value %}<tr><th style="text-align:left;width:40%;padding:5px 7px;background:#f6f6f6;border:1px solid #ddd;font-weight:600;">{{ label }}</th><td style="padding:5px 7px;border:1px solid #ddd;">{{ value }}</td></tr>{% endif -%}
{%- endmacro -%}
{%- set containers = doc.container_details or [] -%}
<div style="font-family:Arial,Helvetica,sans-serif;font-size:12px;color:#111;">
  <table style="width:100%;border-collapse:collapse;border-bottom:2px solid #333;margin-bottom:12px;">
    <tr>
      <td style="padding-bottom:8px;"><h2 style="margin:0;">ARRIVAL NOTICE / إشعار وصول</h2><div>{{ doc.name }}</div></td>
      <td style="padding-bottom:8px;text-align:right;vertical-align:bottom;"><b>Date:</b> {{ frappe.utils.formatdate(frappe.utils.nowdate()) }}</td>
    </tr>
  </table>

  <p style="margin:0 0 4px;"><b>To:</b> {{ doc.customer or "" }}</p>
  {% if doc.to_attention %}<p style="margin:0 0 4px;"><b>Attn:</b> {{ doc.to_attention }}</p>{% endif %}
  <p style="margin:10px 0 12px;">
    Please be informed that the shipment below is expected to arrive{% if doc.eta_date %} on <b>{{ doc.get_formatted("eta_date") }}</b>{% endif %}{% if doc.port_of_destination %} at <b>{{ doc.port_of_destination }}</b>{% endif %}.
  </p>

  <table style="width:100%;border-collapse:collapse;margin-bottom:12px;">
    <tr>
      <td style="width:50%;vertical-align:top;padding-right:6px;">
        <table style="width:100%;border-collapse:collapse;">
          {{ line("Mode / Type", [doc.mode_of_shipment, doc.shipment_type] | select | join(" · ")) }}
          {{ line("BL / AWB No", [doc.awb_number, doc.get_formatted("awb_date") if doc.awb_date else ""] | select | join(" · ")) }}
          {{ line("HBL / HAWB No", doc.house_number) }}
          {{ line("Carrier", doc.carrier or doc.shipping_line or doc.air_line) }}
          {{ line("Vessel / Voyage / Flight", [doc.vessel_name, doc.voyage_number, doc.flight_number] | select | join(" / ")) }}
          {{ line("Port of Loading", doc.port_of_loading) }}
          {{ line("Port of Discharge", doc.port_of_destination) }}
          {{ line("ETA", doc.get_formatted("eta_date") if doc.eta_date else "") }}
        </table>
      </td>
      <td style="width:50%;vertical-align:top;padding-left:6px;">
        <table style="width:100%;border-collapse:collapse;">
          {{ line("Shipper", doc.shipper) }}
          {{ line("Consignee", doc.consignee) }}
          {{ line("Commodity", doc.commodity) }}
          {{ line("Containers", (containers | length ~ " container(s)") if containers else "") }}
          {{ line("Packages", doc.packages or doc.no_of_pieces) }}
          {{ line("Gross Weight", (doc.get_formatted("gross_weight") ~ " " ~ (doc.weight_uom or "")) if doc.gross_weight else "") }}
          {{ line("Volume (CBM)", doc.cbm) }}
          {{ line("Chargeable Weight", doc.get_formatted("chargable_weight") if doc.chargable_weight else "") }}
          {{ line("Free Time", ((doc.free_time_days ~ " days") ~ ((" · until " ~ doc.get_formatted("free_time_expiry")) if doc.free_time_expiry else "")) if doc.free_time_days else "") }}
        </table>
      </td>
    </tr>
  </table>

  {% if doc.cargo_description %}<p style="margin:0 0 12px;"><b>Cargo:</b> {{ doc.cargo_description }}</p>{% endif %}

  {% if containers %}
  <table style="width:100%;border-collapse:collapse;margin-bottom:14px;">
    <thead><tr><th style="border:1px solid #ccc;padding:5px 6px;background:#f2f2f2;text-align:left;">#</th><th style="border:1px solid #ccc;padding:5px 6px;background:#f2f2f2;text-align:left;">Container No</th><th style="border:1px solid #ccc;padding:5px 6px;background:#f2f2f2;text-align:left;">Size / Type</th><th style="border:1px solid #ccc;padding:5px 6px;background:#f2f2f2;text-align:left;">Seal No</th><th style="border:1px solid #ccc;padding:5px 6px;background:#f2f2f2;text-align:left;">Packages</th><th style="border:1px solid #ccc;padding:5px 6px;background:#f2f2f2;text-align:left;">Gross Weight (Kg)</th></tr></thead>
    <tbody>
    {% for c in containers %}
      <tr>
        <td style="border:1px solid #ccc;padding:5px 6px;">{{ loop.index }}</td>
        <td style="border:1px solid #ccc;padding:5px 6px;">{{ c.container_no or "" }}</td>
        <td style="border:1px solid #ccc;padding:5px 6px;">{{ [(c.size ~ "'") if c.size else "", c.container_type] | select | join(" ") }}</td>
        <td style="border:1px solid #ccc;padding:5px 6px;">{{ c.seal_no or "" }}</td>
        <td style="border:1px solid #ccc;padding:5px 6px;">{{ c.packages or "" }}</td>
        <td style="border:1px solid #ccc;padding:5px 6px;">{{ c.get_formatted("weight") if c.weight else "" }}</td>
      </tr>
    {% endfor %}
    </tbody>
  </table>
  {% endif %}

  <p style="margin:0 0 6px;">
    Please send the original documents and any required permits so customs clearance can start on arrival.
    {% if doc.free_time_expiry %}Containers must be returned by <b>{{ doc.get_formatted("free_time_expiry") }}</b> to avoid demurrage and detention charges.{% endif %}
  </p>
</div>
